    public async Task FramesAndTimingMatchLibavif(string file, int bd, int w, int h, long timescale, int loops,
        string durations, string refs)
    {
        byte[] data = File.ReadAllBytes(Asset(file));
        using var seq = HeifCoder.DecodeSequence(data);
        string[] perFrame = refs.Split('|');
        await Assert.That(seq.Count).IsEqualTo(perFrame.Length);
        await Assert.That(seq.Timescale).IsEqualTo(timescale);
        await Assert.That(seq.LoopCount).IsEqualTo(loops);
        await Assert.That(string.Join(",", seq.Frames.Select(f => f.DurationTicks))).IsEqualTo(durations);
        int max = (1 << bd) - 1, worst = 0;
        for (int i = 0; i < seq.Count; i++)
        {
            var img = seq[i];
            await Assert.That((int)img.Columns).IsEqualTo(w);
            await Assert.That((int)img.Rows).IsEqualTo(h);
            int ch = img.NumberOfChannels;
            foreach (var m in System.Text.RegularExpressions.Regex.Matches(perFrame[i], @"\((\d+),(\d+),(\d+),(\d+),(\d+),(\d+)\)"))
            {
                var g = ((System.Text.RegularExpressions.Match)m).Groups;
                int y = int.Parse(g[1].Value), x = int.Parse(g[2].Value);
                var row = img.GetPixelRow(y);
                for (int c = 0; c < 4; c++)
                {
                    int v16 = c < 3 ? row[x * ch + c] : img.HasAlpha ? row[x * ch + ch - 1] : 65535;
                    int ours = (int)Math.Round(v16 * (double)max / 65535.0);
                    worst = Math.Max(worst, Math.Abs(ours - int.Parse(g[3 + c].Value)));
                }
            }
        }
        await Assert.That(worst).IsEqualTo(0);

        // libavif's AUTO source: an 'avis' file decodes as its sequence, so the single-image decode is frame 0.
        var first = HeifCoder.Decode(data);
        await Assert.That(first.GetPixelRow(h / 2).ToArray()).IsEquivalentTo(seq[0].GetPixelRow(h / 2).ToArray());
    }

    // EncodeAvifSequence -> DecodeSequence: frame count, timing, loop count and pixels (PSNR; exact for lossless), across
    // depths, layouts, alpha, grey and lossless.
    [Test]
    [Arguments(8, AvifChromaSubsampling.Auto, false, false, false)]
    [Arguments(8, AvifChromaSubsampling.Auto, true, false, false)]
    [Arguments(10, AvifChromaSubsampling.Yuv444, true, false, false)]
    [Arguments(12, AvifChromaSubsampling.Yuv422, false, false, false)]
    [Arguments(8, AvifChromaSubsampling.Auto, false, true, false)]
    [Arguments(8, AvifChromaSubsampling.Auto, true, false, true)]
    public async Task EncodeSequence_RoundTrips(int bd, AvifChromaSubsampling sub, bool alpha, bool grey, bool lossless)
    {
        var seq = new ImageSequence { Timescale = 1000, LoopCount = 2 };
        for (int k = 0; k < 4; k++)
        {
            var f = new ImageFrame();
            f.Initialize(72, 48, ColorspaceType.SRGB, alpha);
            int ch = f.NumberOfChannels;
            for (int y = 0; y < 48; y++)
            {
                var row = f.GetPixelRowForWrite(y);
                for (int x = 0; x < 72; x++)
                {
                    int v = (int)(32767 + 30000 * Math.Sin((x + 4 * k) * 0.11) * Math.Cos((y - k) * 0.09));
                    row[x * ch] = (ushort)v;
                    row[x * ch + 1] = (ushort)(grey ? v : 65535 - v);
                    row[x * ch + 2] = (ushort)(grey ? v : (int)(32767 + 30000 * Math.Cos((x + y + 3 * k) * 0.05)));
                    if (alpha) row[x * ch + 3] = (ushort)(65535 - ((x + y + 7 * k) * 600) % 65536);
                }
            }
            f.DurationTicks = 40 * (k + 1);
            seq.AddFrame(f);
        }
        var opt = new AvifEncodeOptions { Qp = 12, BitDepth = bd, ChromaSubsampling = sub, Lossless = lossless };
        byte[] avif = HeifCoder.EncodeAvifSequence(seq, opt);
        await Assert.That(System.Text.Encoding.ASCII.GetString(avif, 8, 4)).IsEqualTo("avis");
        using var back = HeifCoder.DecodeSequence(avif);
        await Assert.That(back.Count).IsEqualTo(4);
        await Assert.That(back.Timescale).IsEqualTo(1000L);
        await Assert.That(back.LoopCount).IsEqualTo(2);
        await Assert.That(string.Join(",", back.Frames.Select(f => f.DurationTicks))).IsEqualTo("40,80,120,160");
        for (int k = 0; k < 4; k++)
        {
            var a = seq[k];
            var b = back[k];
            await Assert.That(b.HasAlpha).IsEqualTo(alpha);
            double se = 0;
            int n = 0, worst = 0;
            for (int y = 0; y < 48; y++)
            {
                var ra = a.GetPixelRow(y);
                var rb = b.GetPixelRow(y);
                for (int i = 0; i < 72 * a.NumberOfChannels; i++)
                {
                    int d = (ra[i] - rb[i]) / 257;
                    se += d * d;
                    n++;
                    worst = Math.Max(worst, Math.Abs(ra[i] - rb[i]));
                }
            }
            if (lossless)
                await Assert.That(worst).IsLessThanOrEqualTo(128);   // 8-bit lossless: exact after the 16 -> 8 -> 16 round
            else
                await Assert.That(10 * Math.Log10(255.0 * 255.0 / Math.Max(se / n, 1e-9))).IsGreaterThan(30.0);
        }
        // Still-image readers get frame 0 through the primary item.
        var still = HeifCoder.Decode(avif);
        await Assert.That(still.GetPixelRow(20).ToArray()).IsEquivalentTo(back[0].GetPixelRow(20).ToArray());
    }

    [Test]
    public async Task StillAvifDecodesAsOneFrameSequence()
    {
        byte[] data = File.ReadAllBytes(Asset("sharpimage_8bit_420_161x97_alpha.avif"));
        using var seq = HeifCoder.DecodeSequence(data);
        await Assert.That(seq.Count).IsEqualTo(1);
        await Assert.That((int)seq[0].Columns).IsEqualTo(161);
    }
}
